INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,status,url_slug,created_at,updated_at) VALUES
('mechanical-man','Mechanical Man','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"mechanical-man","name":"Mechanical Man","team":"townsfolk","ability":"Each night, receive a task from the Storyteller. If completed before dusk, receive information about the game that night.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"6reetin(g)s, Ma5ter. 1 live 7o /serve/. I /serve/ to liv3. Aw4iting inpu7.","lede":"The Mechanical Man performs outrageous, risky tasks to learn valuable information.","howToRun":["Tasks are very much up to each individual Storyteller, but some examples might include:","Nominate a neighbour for no reason","Give X player a Mezepheles word","Claim to have heard, and announce specific information from a role in town","Hold a chat in a public room with a certain amount of people, or a certain person","Claim Minion and guess the Damsel","Provide a true piece of information in line with what a Savant might receive. Tasks - and information - should scale in risk/reward as the game progresses."],"tips":["This is an extremely versatile role that learns valuable information about the game state each night, so - do your tasks! Though some may put you in danger, arouse suspicion, or flat out compromise other players, if you’re set on receiving your info, don’t let that stop you. Of course, you always have the choice of failing to perform your task for the day, which, while sacrificing information, can lend you a lot of credibility. In instances where it’s permitted, you can even perform your tasks while informing the player(s) involved that your next action is part of your task, which will hopefully help to keep you from looking evil, but may also gain the evil team’s attention."],"bluffing":["Storytellers can give outrageous requests to a Mechanical Man, so pull off unlikely acts, share Mezepheles words, nominate with abandon. so long as it’s all done under the cover of being the Mechanical Man, not only can you spread chaos around town, but your fake information can drive town towards worlds that simply don’t exist."],"fighting":[],"examples":["Jaz is the Mechanical Man. They are tasked with self-nominating, claiming to be the Lleech host. They do so without revealing their task, and learn that night that one of their neighbours is the Cerenovus.","Kris is the Godfather bluffing as the Mechanical Man. He brings his Demon into a private chat for most of the day under the guise of a task. He announces the next morning that he was informed that the person he spoke with as part of his task is good."],"firstNight":65,"firstNightReminder":"Give the Mechanical Man a task that they must complete. This task can be completed the following day, or any subsequent day.","otherNight":70,"otherNightReminder":"If the Mechanical Man has completed their task, provide information about the game and give the Mechanical Man a new task that they must complete. If no task was completed, only give a new task.","reminders":["Task","Task","Task","Task","Task","Task","Task Complete"],"setup":false,"image":"https://menagerie.towerrangers.net/images/mecg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/mece.png"}','published','the-menagerie/mechanical-man',datetime('now'),datetime('now')),
('medicine-man','Medicine Man','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"medicine-man","name":"Medicine Man","team":"townsfolk","ability":"Each night, learn if either of your living neighbours are poisoned, drunk or mad.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Hush, now. One spoonful of wild sage; a pinch of rosehip; a dash of calendula; boiled with nettle should do it. But drink quickly - you are fading fast… and this tastes terrible.","lede":"The Medicine Man can detect many ills, from madness to poisoning.","howToRun":["Remember that poisoning and drunkenness demand arbitrary information: if good is winning, consider giving poisoned or drunk players arbitrarily correct information if the Medicine Man is aware that they may be affected."],"tips":["Your ability to sniff out forms of drunkenness, poisoning or madness is invaluable to your team, so finding individuals who may be impacted means you’ll be able to verify information, explain certain behaviours, or provide an explanation for misfiring abilities. This becomes especially powerful in situations where certain statuses are permanent, like the No Dashii’s poisoning, Sweetheart drunkenness, or Mutant madness. So long as you have reason to believe that your own information is sober, you should be a valuable asset to your team."],"bluffing":["As a Minion or Demon, you’ll have insight as to who is impacted by negative statuses, so you have the option of gaining trust by verifying them. However, you can also spread misinformation to get specific good players to not trust their information - which, as above in situations like No Dashii poisoning or Sweetheart drunkenness could lead the opposing team to lean into worlds that are patently false. And if you get called out on your shoddy information, you can always back into you yourself being poisoned or drunk!"],"fighting":[],"examples":["Brian is the Medicine Man. He learns a 1 on Night 3, suggesting that one player''s information might be unreliable.","Mary is the No Dashii bluffing as the Medicine Man. She claims to have received a 0 on Night 1, meaning her neighbours can''t possibly be poisoned."],"firstNight":46,"firstNightReminder":"The Medicine Man learns a yes or no.","otherNight":57.5,"otherNightReminder":"The Medicine Man learns a yes or no.","reminders":[],"setup":false,"jinxes":[{"name":"Mutant","align":"good","text":"The Mutant registers as mad to the Medicine Man.","id":"mutant"},{"name":"Sleeper","align":"good","text":"The Sleeper, and the Minion they are making drunk, register as mad to the Medicine Man.","slug":"sleeper-the-menagerie"},{"name":"Mime","align":"good","text":"The Mime registers as mad to the Medicine Man if they are to learn information tonight.","slug":"mime-the-menagerie"},{"name":"Yang","align":"good","text":"The Yang registers as mad to the Medicine Man.","slug":"yang"}],"image":"https://menagerie.towerrangers.net/images/medg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/mede.png"}','published','the-menagerie/medicine-man',datetime('now'),datetime('now')),
('mentalist-the-menagerie','Mentalist','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"mentalist-the-menagerie","name":"Mentalist","team":"townsfolk","ability":"Each night*, learn the character of a living player you had a private chat with today. If you spoke with only one living player, this info is false.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"I don''t need to see the future. I just need to understand the present. (Creator credit: Mega)","lede":"The Mentalist learns about who they speak to privately.","howToRun":["If the Mentalist speaks with multiple players, consider giving roles that don''t lead to massive confirmation chains."],"tips":["Talk, talk, talk! Your ability to extract information is moderated by who you speak to, and in what quantity. Speak with players who you have suspicion around to confirm them one by one - or hold a private chat with just one player to learn them specifically - but know that doing so will hamper your ability to gather claims and info from other players. How you play the Mentalist depends on what you hope you achieve with the role, but know that staying isolated in town will likely signal to the Demon that you''re trying to gather Mentalist info."],"bluffing":["If you claim to be the Mentalist, people will likely want to \"test\" you - so having knowledge of roles is handy. With that said, you can always use your Mentalist bluff to help confirm evil players, and legitimise their claims by suggesting that they exist when the time comes. Mixing the confirmation of bluffs with real information is a great way to lend yourself credibility, helping town infer that you might be what you state."],"fighting":[],"examples":["Wei is the Mentalist who speaks with four people on the first day. At night, Wei learns that one of them is the Dentist.","Attie is the Fearmonger posing as the Mentalist. They chat with their evil team on Day 1 and claim to learn that one of those players is the Seer. They chat with a further four players the next day and claim to learn that among them is the Oracle."],"firstNight":0,"firstNightReminder":"","otherNight":70,"otherNightReminder":"Wake the player, and show them a character of a living player they spoke with privately.","reminders":["Chatted","Chatted","Chatted","Chatted","Chatted","Chatted","Chatted","Chatted","Chatted","Chatted","Chatted","Chatted","Chatted"],"setup":false,"image":"https://menagerie.towerrangers.net/images/meng.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/mene.png"}','published','the-menagerie/mentalist',datetime('now'),datetime('now')),
('mortician','Mortician','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"mortician","name":"Mortician","team":"townsfolk","ability":"Once per game*, at night, choose an alive player. The Undertaker, if chosen, learns a character killed at night. Each night, learn if dead neighbours are targeted by an ability. [+the Undertaker]","creator":"Goodpart","appearsIn":"The Menagerie","quote":"It''s thankless work, but I''d be concerned if it wasn''t.","lede":"The Mortician adds and aids the Undertaker - and keeps an eye on deceased neighbours.","howToRun":["The Mortician enhances, and in a sense, protects the Undertaker, so ensure that the bag built takes this into consideration. Consider pairing the Mortician with Demons such as the Ojo, or Minions such as the Spy to ensure that the Undertaker can be sufficiently bluffed."],"tips":["As is the case with the Huntsman or Choirboy, your existence implies the existence of the Undertaker - so go and find them! Creating a chain of confirmation with such a powerful role is incredibly useful, and finding the Undertaker means that you''re able to activate your ability for as long as they live. While you need to trust who you select at night, if confirmed, you can likely trust your pick until the very end."],"bluffing":["Like many \"pair\" roles, you''re often able to take two bluffs for the price of one. If you receive Undertaker as a bluff, you know that the Mortician is also up for grabs. Keep in mind that bluffing Mortician with an Undertaker in play is tricky, since there is a mechanical basis to your ability, but given how often strong roles try to hide behind the Undertaker''s role, you might want to consider \"choosing\" them in the night to waste your ability."],"fighting":[],"examples":["Gideon is the Mortician. On Night 2, he learns that one of his dead neighbours was targeted by an ability - the dead Oracle reveals on a later day that they were Cerenovus mad. Gideon also chooses Reginald as part of his ability: Reginald learns that the Demon killed the High Priestess that night.","Angela is the Poisoner bluffing as the Mortician. They claim to have selected the Ravenkeeper as their Undertaker pick, who learns nothing. Angela also notes that on the same night, the now-dead Cerenovus may have been selected at night, implying they are currently mad."],"firstNight":0,"firstNightReminder":"","otherNight":60,"otherNightReminder":"Wake the Mortician: they may choose to use their ability. If they agree, they choose a player. The Undertaken, if chosen, is woken. Show them a character that has died tonight. Nod or shake your head at the Mortician depending on whether a dead neighbour was targeted by an ability.","reminders":["Learned","No Ability","Targeted","Targeted"],"setup":true,"jinxes":[{"name":"Philosopher","align":"good","text":"If the Philosopher has the Undertaker''s ability, they receive info from the Mortician. If alive, the Undertaker receives false info.","id":"philosopher"}],"image":"https://menagerie.towerrangers.net/images/morg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/more.png"}','published','the-menagerie/mortician',datetime('now'),datetime('now')),
('old-sheriff','Old Sheriff','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"old-sheriff","name":"Old Sheriff","team":"townsfolk","ability":"You start knowing how many evil players are sitting within 3 steps of you. This number may be 1 higher or lower. [-1 Outsider]","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Upholdin’ the law’s tough work, but if you’re real careful-like, you just might see the autumn years. ’Course, it goes without sayin’ – you should never trust an ol’ man in a young man’s game, heh.","lede":"The Old Sheriff''s eye for evil isn''t what it used to be, but they still keep undesirables out of town.","howToRun":["Running the Old Sheriff is very simple, but do take care when removing Outsiders – you may inadvertently hamstring characters like the Godfather or Fang Gu, which rely on Outsiders to function properly."],"tips":["As the old town’s sheriff, you aren’t quite what you used to be, but you still do a fine enough job of keeping the order. Although learning how many evil players sit near you is valuable information, remember that this number may be either one higher or lower than it should be. Take that into account when relaying this information, but of course, if the number you receive is incredibly high, aside from being poisoned or drunk, you can reliably assume that at least someone near you is evil. Thankfully, your ability to curb Outsiders means that the majority of your job is already done at the start of the game, so even if your ability can’t be fully relied upon, at least you’ve done your job as best you can."],"bluffing":["The Old Sheriff works best with Minions that might remove Outsiders, since it mimics his own setup ability. With that said, if you’re confident there is a Drunk in play, you can get away with bluffing as the Old Sheriff to ensure that town affords their information far more certainty than they probably should. Additionally, the number you provide can be kept nice and low to protect any nearby evil players; or raise it sky-high to implicate some of your neighbours."],"fighting":[],"examples":["Zach is the Old Sheriff. He learns that there are 2 evils within 3 steps of him; the actual number is 1.","Justin is the Baron bluffing as the Old Sheriff. He suggests there are 0 evils within 3 steps of him, despite the fact that he neighbours the Demon and the Poisoner."],"firstNight":64,"firstNightReminder":"Give the Old Sheriff a number corresponding to the number of evil players within 3 steps of them either side, 1 higher or lower than the actual number.","otherNight":0,"otherNightReminder":"","reminders":[],"setup":true,"image":"https://menagerie.towerrangers.net/images/sherg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/shere.png"}','published','the-menagerie/old-sheriff',datetime('now'),datetime('now')),
('prophet-the-menagerie','Prophet','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"prophet-the-menagerie","name":"Prophet","team":"townsfolk","ability":"Each day, before nominations, you may make a public statement about today’s executee. At night, learn if it was true.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"I sense… a fair complexion, shoulder-length auburn hair… weathered hands… good of heart… it is you! The town washerwoman - today, you will meet your end! So say I, so shall it be.","lede":"The Prophet sees into the future to learn about the player about to be executed that day.","howToRun":["As with the Gossip, players can’t prophecise about things that are yet to happen: the prophecy is true or false at the time that it is made, and can only be confirmed via the game state at that moment."],"tips":["You have the ability to confirm players in whatever way you wish, so make the most of your prophecies. You may want to keep it quite general, ie. “Player X is good”, or perhaps be more specific, ie. “Player Y is either the Gatekeeper or the Dreamer”. Whatever you choose to go with, receiving confirmation from the Storyteller will help your team solve the game, and sometimes, learning that your prophecy is false can lead to other conclusions – so don’t fret if you don’t get the answer you’re after."],"bluffing":["Given that you know who the evil players are around the Grimoire, you’ll be much better equipped to make plausible-sounding prophecies. Although you can’t receive confirmation around what you say, you can bluff it to either clear recently executed teammates, or to implicate others. Take care that the misinformation you spread isn’t disproven elsewhere."],"fighting":[],"examples":["Freddie is the Prophet. He publicly claims that today''s executee is an Outsider. He learns at night that it was true.","Angel is the Spy bluffing as the Prophet. She publicly claims that today''s executee - next to the Monk and the Plague Doctor - neighbours an evil player, and states that the next day that it was true."],"firstNight":0,"firstNightReminder":"","otherNight":65,"otherNightReminder":"Give the Prophet a yes/no depending on whether their statement about the day’s executee was true. If no-one was executed today, do not wake the Prophet.","reminders":["Prophecised"],"setup":false,"image":"https://menagerie.towerrangers.net/images/prog.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/proe.png"}','published','the-menagerie/prophet',datetime('now'),datetime('now')),
('ronin-the-menagerie','Ronin','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"ronin-the-menagerie","name":"Ronin","team":"townsfolk","ability":"On your first night, you and the Demon learn two players, one of which is your ally. If the Demon kills your ally, learn an evil player, and the 1st time you die, you don''t.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"身をあさく思、世をふかく思ふ.","lede":"The Ronin becomes unstoppable when their charge has been slain.","howToRun":["Balance the Ronin''s effect around the relative ''strength'' of the learned players: if evil is in a strong position from the start of the game, the Ronin might learn a character unlikely to die to the Demon, and vice versa.","In a Vortox game, or if the Ronin is poisoned, the Ronin must - or might - learn a different player to the one you mark."],"tips":["Protect your learned players at all costs... during the day! When it''s the Demon''s time to act, if your learned player dies to the Demon, you now have the ability to defy death, with an evil player in your sights."],"bluffing":["Your charge is the basis of your ability, so keeping them alive during the day is key. As such, you can tie yourself to a player that you want - or need - to protect, such as a Minion or Demon. And if that player is, for instance, a star-passing Imp, or a Fang Gu that jumps to an Outsider, you can always claim to be poisoned in some fashion, hence why your ability isn''t firing... or, alternatively, on a night of two kills, imply that a Godfather or Assassin did the job instead. It''s risky, but it can certainly be done."],"fighting":[],"examples":["Lili is the Ronin. They learn Jake - the Librarian - and Mark - the Godfather - on Night 1. On Night 4, Jake is killed by the Demon: Lili gains their ability from then on.","Mike is the Assassin bluffing as the Ronin. Their \"charge\" is the Fang Gu. The Fang Gu signals that they will jump on Night 3. The new Fang Gu kills a corpse the next night, implying that Mike was targeted."],"firstNight":37,"firstNightReminder":"Mark a player with the Ally token and another with the Wrong token . Wake the Ronin and show them those players. Wake the Demon and show them those players.","otherNight":57.5,"otherNightReminder":"If the Ronin''s learned player has died tonight, wake the Ronin and show them an evil player. Mark the Ronin with the Has Ability token .","reminders":["Ally","Wrong","Died Once"],"setup":false,"image":"https://menagerie.towerrangers.net/images/ronig.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/ronie.png"}','published','the-menagerie/ronin',datetime('now'),datetime('now')),
('seer-the-menagerie','Seer','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"seer-the-menagerie","name":"Seer","team":"townsfolk","ability":"Each night, the Demon chooses 1 alive player (not a Minion or Demon), unique to previous choices. Learn that player. If you are chosen, the Demon learns who you are.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"These visions can be wielded as a weapon - but all too often, people of my ilk find those weapons turned against me.","lede":"The Seer forces the Demon to confirm who is good, but if ever found, knows they are on borrowed time.","howToRun":["If the Seer is ever Drunk or poisoned, you are still obligated to wake the Demon to choose a player, however the Seer will learn arbitrary information. If the Seer is chosen while drunk or poisoned, the Demon does not learn who the Seer is."],"tips":["Stay alive! Your survival is your best chance to gain solid information about trustworthy players around the Grimoire. Knowing that the Demon is actively hunting for you means that arousing as little suspicion as possible is paramount. And, of course, if you ever learn your own name, you know that the Demon now knows precisely who you are - and will likely target you at the next possible opportunity. Call their bluff, reveal your information, and hope that town trusts you."],"bluffing":["Simply put, if you are evil, it is highly likely that you know who the good players around the Grimoire are - use this to your advantage and curry their favour by signalling to them that the Demon chose them in the night, and that you learned their name - and sprinkle in some trusted evil players for good measure. Just remember that it’s difficult to bluff as the Seer in the long term given that the Demon should eventually find you."],"fighting":[],"examples":["Alice is the Seer. They learn three names before learning themselves on Night 4. They know they have been found, and die on Night 5.","TJ is the Cerenovus bluffing as the Seer. They \"confirm\" their Demon, claim to learn their own name, and are then killed by the Vigor Mortis the night after."],"firstNight":47,"firstNightReminder":"The Demon selects a player. Show that player to the Seer if they are good; show an arbitrary player if they are drunk. If the Demon chooses the Seer, show the Seer''s player to the Demon.","otherNight":57.5,"otherNightReminder":"The Demon selects a player. Show that player to the Seer if they are good; show an arbitrary player if they are drunk. If the Demon chooses the Seer, show the Seer''s player to the Demon.","reminders":["Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Chosen","Learns"],"setup":false,"jinxes":[{"name":"Goon","align":"good","text":"If the Goon has not been chosen tonight, they become the alignment of the Seer, not the Demon; the Seer is drunk as a result.","id":"goon"},{"name":"Spy","align":"good","text":"The Spy can be chosen by the Demon at night.","id":"spy"},{"name":"Summoner","align":"good","text":"If a Summoner is in play and no Demon is in play, the Summoner chooses for the Seer’s ability instead.","id":"summoner"},{"name":"Doppelganger","align":"good","text":"The Doppelganger can be chosen by the Demon at night.","slug":"doppelganger-the-menagerie"},{"name":"Vortox","align":"good","text":"The Vortox can choose any player at night as part of the Seer''s ability.","id":"vortox"}],"image":"https://menagerie.towerrangers.net/images/seeg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/seee.png"}','published','the-menagerie/seer',datetime('now'),datetime('now'));